/**
 * greet somebody
 *
 * @namespace demo
 * @example usage
```javascript
greet({name: 'Ann'})
```
 **/    
declare function greet({name; times = 2; loud = false; label = 'x'; neg = -1; nothing}: {
/**
who to greet, e.g. Ann
 */
 name: any; 
/**
how often
 */
 times: any; 
/**

 */
 loud: any; 
/**

 */
 label: any; 
/**

 */
 neg: any; 
/**

 */
 nothing: any}): { ok: boolean; greeting: any; };

/**
 * no params
 *
 * 
 * 
 **/    
declare function ping(): { ok: boolean; };

